import{_ as s,l as i,o as e,c as d,v as o,p as n,x as t,d as l,i as c,S as A}from"./chunks/framework.InCnrqk-.js";const P=JSON.parse('{"title":"总线与 MMIO","description":"","frontmatter":{"title":"总线与 MMIO","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/bus-mmio.md","filePath":"cs/bus-mmio.md","lastUpdated":1789023840000}'),m={name:"cs/bus-mmio.md"};function p(E,a,h,M,u,_){const r=i("Mermaid");return e(),d("div",null,[a[1]||(a[1]=o('<h1 id="总线与-mmio" tabindex="-1">总线与 MMIO <a class="header-anchor" href="#总线与-mmio" aria-label="Permalink to &quot;总线与 MMIO&quot;">​</a></h1><div class="epigraph"><p>CPU 的访存口接到一组共享地址/数据/控制线上；一段物理地址不对应 DRAM 单元，而对应外设寄存器，这就是内存映射 I/O。</p><footer>—— 据 Patterson and Hennessy, Computer Organization and Design (RISC-V)；Harris and Harris, Digital Design and Computer Architecture 整理</footer></div><p>上一课<a href="/cs/multicycle-microcode">多周期与微程序直觉</a>让硬件能把指令拆拍执行。本课不重画 FSM 状态，也不从操作系统驱动模型另起。缺口是：到现在「数据存储器」还是一块匿名阵列。真实系统里，同一套 <code>lw</code>/<code>sw</code> 还要打到<strong>外设</strong>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>总线：地址、数据、读/写、就绪。主设备（CPU）发起，从设备（存储控制器、UART）译码地址片选。MMIO：物理地址区间译到设备寄存器，软件仍用 load/store，没有单独 <code>in</code>/<code>out</code>（x86 端口 I/O 是另一风格，本栏不用）。缺口不是新的 ISA 运算，而是地址译码把空间切开。</p><p>就绪信号让慢设备插入等待拍，与多周期「等存储器」同一机制。教学单周期常假装一拍完成。</p><h3 id="mmio-不是「另一套指令集」" tabindex="-1">MMIO 不是「另一套指令集」 <a class="header-anchor" href="#mmio-不是「另一套指令集」" aria-label="Permalink to &quot;MMIO 不是「另一套指令集」&quot;">​</a></h3><p>外设寄存器的比特语义是设备规定的，但访问就是普通 <code>lw</code>/<code>sw</code>。把 MMIO 当成需要新 opcode 的 I/O 指令，RISC-V 的 load/store 原则会破。缓存：MMIO 区通常不可缓存，否则写缓冲会打乱设备顺序——体系结构课再钉，本课承认「有的地址不是 RAM」。</p><p><span class="marginnote">Patterson/Hennessy 用内存映射设备。Harris 有简单总线时序。三态/互斥驱动已在<a href="/cs/transmission-tristate">传输门与三态</a>。本课不把 PCIe 层次写完。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>CPU 发出地址。译码：落在 RAM 则进 DRAM/SRAM 控制器；落在 <code>0x10000000</code> 一类窗口则进 UART 等。设备把寄存器接到总线数据。轮询：软件读状态位。中断通知留到后课入口与 PLIC。</p>',11)),(e(),n(A,null,{default:t(()=>[c(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20CPU%5B%22CPU%20load%2Fstore%22%5D%20--%3E%20BUS%5B%22%E5%9C%B0%E5%9D%80%E6%95%B0%E6%8D%AE%E6%8E%A7%E5%88%B6%22%5D%0A%20%20BUS%20--%3E%20RAM%5B%22%E5%AD%98%E5%82%A8%E5%99%A8%E7%AA%97%E5%8F%A3%22%5D%0A%20%20BUS%20--%3E%20DEV%5B%22%E8%AE%BE%E5%A4%87%E5%AF%84%E5%AD%98%E5%99%A8%E7%AA%97%E5%8F%A3%22%5D%0A%20%20DEV%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E8%BD%AF%E4%BB%B6%E8%B0%83%E7%94%A8%E7%BA%A6%E5%AE%9A%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>至此，组成上的处理器能执行任意已定义指令序列，并能用地址访问存储与设备。下一课不再加数据通路方框，而是软件如何用 <code>jal</code> 与栈传参——硬件已经够用。DMA 是设备当主设备抢总线，本课点名，机制同仲裁。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲 VirtIO、不把网络协议栈请进来。不讨论一致性下 MMIO 的强序。中断号如何汇聚是 PLIC 课。</p><p>后课默认：I/O 是 load/store 到特殊物理地址；总线有等待。下一课 ABI 与栈。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>总线连接 CPU 与从设备；MMIO 用访存指令打设备。</li><li>地址译码区分 RAM 与寄存器。</li><li>硬件已能跑任意指令序列；下一课是软件约定。</li><li>出处：Patterson and Hennessy, COD (RISC-V)；Harris and Harris。</li></ul>',7))])}const B=s(m,[["render",p]]);export{P as __pageData,B as default};
